from .branding import COMMON_CSS, LOGO_DATA_URI

TOOLS_HTML = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AGENT WHITE TOOL CENTER</title><style>
__AW_COMMON_CSS__
.tool-layout{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(350px,.8fr);gap:10px}.quick-grid,.tool-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.tool-card{min-height:190px}.title{font-weight:800;font-size:13px}.familybar,.filters,.summary,.meta{display:flex;gap:6px;flex-wrap:wrap;align-items:center}.familybar{margin:8px 0}.family.active{border-color:var(--aw-green);color:var(--aw-green);box-shadow:0 0 15px rgba(0,245,154,.08)}.adapter{margin-top:9px;padding-top:8px;border-top:1px solid rgba(0,245,154,.12)}.adapter-row{padding:8px;margin-top:6px;border:1px solid rgba(0,245,154,.12);border-radius:7px;background:rgba(0,9,7,.55)}.history{border-left:3px solid var(--aw-cyan);margin-bottom:7px}.policy,.setup-note{margin-top:8px;padding:7px;border:1px solid rgba(0,245,154,.12);border-radius:7px;background:#010605;color:#84d9b8;font-size:10px}.setup-note.installable{border-color:rgba(37,223,255,.28);color:#b9ecff}.setup-note.other{border-color:rgba(255,212,91,.22);color:#e8cf88}.filters input{min-width:260px;flex:1;background:#010605;color:white;border:1px solid rgba(0,245,154,.18);border-radius:7px;padding:8px}.sticky-side{display:grid;gap:10px;align-content:start}.action-count{font-size:28px;font-weight:900;color:var(--aw-green)}.setup-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px}.setup-stat{padding:9px;border:1px solid rgba(0,245,154,.13);border-radius:7px;background:rgba(1,8,7,.65)}.setup-stat b{display:block;font-size:21px;color:var(--aw-cyan)}@media(max-width:1100px){.tool-layout{grid-template-columns:1fr}.sticky-side{grid-template-columns:1fr 1fr}}@media(max-width:760px){.tool-grid,.quick-grid,.sticky-side,.setup-grid{grid-template-columns:1fr}}
</style></head><body><div class="aw-app"><aside class="aw-sidebar"><div class="aw-brand"><img class="aw-logo" src="__AW_LOGO__" alt="Agent White logo"><div><div class="aw-wordmark">AGENT <span>WHITE</span></div><div class="aw-tagline">TOOL CENTER · SETUP CENTER</div></div></div><nav class="aw-nav"><a href="/"><span class="ico">▦</span>Dashboard</a><a href="/workspace"><span class="ico">◎</span>Targets</a><a href="/workspace"><span class="ico">⌘</span>Network</a><a href="/ai"><span class="ico">◉</span>Intelligence</a><a href="/workspace"><span class="ico">⊕</span>Threat Hunting</a><a class="active" href="/tools"><span class="ico">⌁</span>Tools</a><a href="/api/export" target="_blank"><span class="ico">▤</span>Reports</a><a href="/ai"><span class="ico">✦</span>AI Analyst</a></nav><div class="aw-sidebar-foot"><span class="aw-green">● ADAPTER BUS ONLINE</span><br>AUTO-CHAIN OFF</div></aside><main class="aw-main"><div class="aw-topbar"><div class="aw-search"><input id="search" placeholder="Search tools, protocols, hardware…" oninput="renderTools()"></div><div class="aw-topstatus"><span class="aw-pill ok">Tool Registry Online</span><span class="aw-pill">Fixed Recipes Only</span></div></div>
<div class="tool-layout"><div><section class="aw-panel"><div class="aw-panel-head"><h2>⚒ QUICK ACTIONS</h2><span class="aw-right aw-muted">Detected tools only</span></div><div class="aw-panel-body"><div id="quick" class="quick-grid"><div class="aw-empty">Loading approved actions…</div></div></div></section><section class="aw-panel" style="margin-top:10px"><div class="aw-panel-head"><h2>▦ TOOL FAMILIES</h2><span id="count" class="aw-right aw-muted">Loading…</span></div><div class="aw-panel-body"><div id="summary" class="summary"></div><div id="familybar" class="familybar"></div><div class="filters" style="margin-top:8px"><button class="aw-btn" onclick="setMode('all')">All</button><button class="aw-btn" onclick="setMode('installed')">Ready</button><button class="aw-btn" onclick="setMode('missing')">Needs Setup</button></div><div id="tools" class="tool-grid" style="margin-top:9px"><div class="aw-empty">Loading registry…</div></div></div></section></div><div class="sticky-side"><section class="aw-panel"><div class="aw-panel-head"><h2>◈ SETUP CENTER</h2></div><div class="aw-panel-body"><div id="setup-summary" class="setup-grid"></div><div class="setup-note" style="margin-top:8px">“Not detected” no longer means “broken.” AgentWhite now separates bundled engines, one-click installs, other-OS tools, and hardware/manual setup.</div></div></section><section class="aw-panel"><div class="aw-panel-head"><h2>◈ CONTROL STATUS</h2></div><div class="aw-panel-body"><div class="aw-card"><div class="aw-muted">Approved UI actions</div><div id="approved-count" class="action-count">0</div></div><div class="aw-card" style="margin-top:7px"><div class="aw-row"><span>Raw command input</span><span class="aw-right aw-red">BLOCKED</span></div><div class="aw-row"><span>Auto-chain</span><span class="aw-right aw-red">OFF</span></div><div class="aw-row"><span>Local result history</span><span class="aw-right aw-green">ON</span></div></div></div></section><section class="aw-panel"><div class="aw-panel-head"><h2>TOOL HISTORY</h2><span class="aw-right aw-muted">Newest first</span></div><div id="history" class="aw-panel-body"><div class="aw-empty">No tool actions have been run yet.</div></div></section></div></div></main></div>
<div id="result-modal" class="aw-modal" onclick="if(event.target===this)closeResult()"><div class="aw-modal-card"><div class="aw-modal-head"><strong id="result-title">TOOL RESULT</strong><button class="aw-btn aw-right" onclick="closeResult()">Close</button></div><div class="aw-panel-body"><div id="result-meta" class="policy"></div><pre id="result-body" class="aw-pre"></pre><div class="aw-actions" style="margin-top:8px"><a class="aw-btn blue" href="/workspace">Open Target Workspaces</a><button class="aw-btn" onclick="closeResult()">Back to Tools</button></div></div></div></div><div id="toast" class="aw-toast"></div>
<script>
let state={tools:[],actions:[],runs:[],setup_summary:{}};let mode='all';let family='all';const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot',"'":'&#039;'}[c]));function toast(msg,error=false){const e=document.getElementById('toast');e.textContent=msg;e.className='aw-toast'+(error?' error':'');e.style.display='block';setTimeout(()=>e.style.display='none',4200)}function setMode(v){mode=v;renderTools()}function familyOf(x){const s=((x.category||'')+' '+(x.target_kinds||[]).join(' ')).toLowerCase();if(s.includes('wi-fi'))return'wifi';if(s.includes('bluetooth')||s.includes(' ble'))return'bluetooth';if(s.includes('rfid')||s.includes('nfc'))return'rfid';if(s.includes('sdr')||s.includes(' rf')||s.includes('zigbee')||s.includes('802.15.4')||s.includes('iot'))return'radio';if(s.includes('can')||s.includes('automotive')||s.includes('industrial'))return'can';if(s.includes('usb')||s.includes('serial')||s.includes('uart'))return'usbserial';if(s.includes('embedded')||s.includes('firmware')||s.includes('jtag')||s.includes('swd')||s.includes('electronics'))return'embedded';return'network'}const familyLabels={all:'ALL',wifi:'WI-FI',bluetooth:'BLUETOOTH',rfid:'RFID / NFC',radio:'RF / SDR / ZIGBEE',network:'NETWORK',embedded:'EMBEDDED',usbserial:'USB / SERIAL',can:'CAN / AUTO'};function setFamily(v){family=v;renderFamilies();renderTools();renderQuick()}async function api(path,opts={}){const r=await fetch(path,{headers:{'Content-Type':'application/json'},cache:'no-store',...opts});let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(d.error||('Request failed: '+r.status));return d}async function load(){state=await api('/api/tools');render()}function render(){document.getElementById('count').textContent=(state.tools||[]).length+' registered tools';document.getElementById('approved-count').textContent=(state.actions||[]).filter(a=>a.available).length;renderSetupSummary();renderFamilies();renderQuick();renderTools();renderHistory()}function renderSetupSummary(){const s=state.setup_summary||{};document.getElementById('setup-summary').innerHTML=`<div class="setup-stat"><span class="aw-muted">Ready</span><b>${s.ready||0}</b></div><div class="setup-stat"><span class="aw-muted">One-click install</span><b>${s.installable||0}</b></div><div class="setup-stat"><span class="aw-muted">Bundled engine issue</span><b>${s.bundled_engine_missing||0}</b></div><div class="setup-stat"><span class="aw-muted">Manual / hardware</span><b>${s.external_setup||0}</b></div><div class="setup-stat"><span class="aw-muted">Other OS</span><b>${s.unsupported_platform||0}</b></div>`}function renderFamilies(){const keys=['all','wifi','bluetooth','rfid','radio','network','embedded','usbserial','can'];document.getElementById('familybar').innerHTML=keys.map(k=>`<button class="aw-btn family ${family===k?'active':''}" onclick="setFamily('${k}')">${familyLabels[k]}</button>`).join('')}function toolActions(id){return(state.actions||[]).filter(a=>a.tool_id===id)}function visibleByFamily(tool){return family==='all'||familyOf(tool)===family}function setupBadge(x){const s=x.setup||{};const ok=s.state==='ready';const color=s.state==='installable'?'style="color:var(--aw-cyan);border-color:rgba(37,223,255,.35)"':s.state==='unsupported-platform'?'style="color:var(--aw-muted)"':'';return `<span class="aw-badge ${ok?'ok':''} aw-right" ${color}>${esc(s.label||'SETUP REQUIRED')}</span>`}function renderQuick(){const tools=state.tools||[],map=new Map(tools.map(t=>[t.id,t]));let acts=(state.actions||[]).filter(a=>a.available);if(family!=='all')acts=acts.filter(a=>{const t=map.get(a.tool_id);return t&&familyOf(t)===family});const el=document.getElementById('quick');if(!acts.length){el.innerHTML='<div class="aw-empty">No detected approved actions in this category yet.</div>';return}el.innerHTML=acts.map(a=>{const t=map.get(a.tool_id)||{};return`<div class="aw-card"><div class="aw-row"><div><div class="title">${esc(a.label)}</div><div class="aw-muted">${esc(t.name||a.tool_id)} · ${esc(a.description)}</div></div><span class="aw-badge ok aw-right">READY</span></div><div class="aw-actions" style="margin-top:8px"><button class="aw-btn primary" onclick="runAction('${esc(a.id)}')">Run This Action</button><span class="aw-chip">${esc(a.effect)}</span><span class="aw-chip">stops after result</span></div></div>`}).join('')}function renderTools(){const rows=state.tools||[],q=(document.getElementById('search').value||'').toLowerCase();let view=rows.filter(visibleByFamily).filter(x=>mode==='all'||(mode==='installed'&&x.installed)||(mode==='missing'&&!x.installed));view=view.filter(x=>JSON.stringify(x).toLowerCase().includes(q));const installed=rows.filter(x=>x.installed).length,ready=(state.actions||[]).filter(a=>a.available).length;document.getElementById('summary').innerHTML=`<span class="aw-badge ok">${installed} tools ready</span><span class="aw-badge ok">${ready} UI actions ready</span><span class="aw-badge">${rows.length-installed} need setup / another OS / hardware</span><span class="aw-badge" style="color:var(--aw-amber)">AUTO-CHAIN OFF</span>`;document.getElementById('tools').innerHTML=view.length?view.map(x=>{const acts=toolActions(x.id),setup=x.setup||{},actionHtml=acts.length?`<div class="adapter"><strong>Buttons</strong>${acts.map(a=>`<div class="adapter-row"><div class="aw-row"><div><div class="title">${esc(a.label)}</div><div class="aw-muted">${esc(a.description)}</div></div><span class="aw-badge ${a.available?'ok':''} aw-right">${a.available?'READY':'WAITING FOR TOOL'}</span></div><div class="aw-actions" style="margin-top:7px"><button class="aw-btn primary" ${a.available?'':'disabled'} onclick="runAction('${esc(a.id)}')">${a.available?'Run This Action':'Tool Not Ready'}</button><span class="aw-chip">fixed recipe</span><span class="aw-chip">no raw args</span></div></div>`).join('')}</div>`:'<div class="adapter aw-muted">No runnable adapter has been approved for this engine yet.</div>';const setupClass=setup.state==='installable'?'installable':setup.state==='ready'?'':'other';let setupAction='';if(setup.installable)setupAction=`<button class="aw-btn blue" onclick="installTool('${esc(x.id)}')">${esc(setup.install_label||'Install Tool')}</button>`;else if(setup.state==='bundled-engine-missing')setupAction='<span class="aw-chip">Update/reinstall AgentWhite</span>';else if(setup.state==='unsupported-platform')setupAction='<span class="aw-chip">Not for this OS</span>';else if(setup.state==='external-setup')setupAction='<span class="aw-chip">External software/hardware setup</span>';return`<div class="aw-card tool-card"><div class="aw-row"><div><div class="title">${esc(x.name)}</div><div class="aw-muted">${esc(x.category)} · ${esc(x.project)}</div></div>${setupBadge(x)}</div><div class="meta"><span class="aw-chip">${esc(familyLabels[familyOf(x)]||'OTHER')}</span><span class="aw-chip">${esc(x.effect)}</span><span class="aw-chip">${esc(x.integration)}</span>${(x.platforms||[]).map(p=>`<span class="aw-chip">${esc(p)}</span>`).join('')}</div><div><strong>Capabilities</strong><div class="aw-muted">${esc((x.capabilities||[]).join(' · '))}</div></div><div style="margin-top:6px"><strong>Hardware</strong><div class="aw-muted">${esc((x.hardware||[]).join(' · ')||'No dedicated hardware requirement')}</div></div><div class="setup-note ${setupClass}"><strong>${esc(setup.label||'SETUP')}</strong><br>${esc(setup.detail||'No setup detail available.')}<div class="aw-actions" style="margin-top:7px">${setupAction}</div></div><div class="policy">Explicit UI action · AUTO-CHAIN OFF · result history ON · active target tests require enrollment</div>${actionHtml}</div>`}).join(''):'<div class="aw-empty">No tools match this category/filter.</div>'}async function installTool(toolId){if(!confirm('Install the approved AgentWhite setup recipe for this tool?'))return;toast('Running the selected setup recipe…');try{const d=await api('/api/tool-setup',{method:'POST',body:JSON.stringify({tool_id:toolId})});state={tools:d.tools||state.tools,actions:d.actions||state.actions,runs:d.runs||state.runs,setup_summary:d.setup_summary||state.setup_summary};render();document.getElementById('result-title').textContent='TOOL SETUP RESULT';document.getElementById('result-meta').textContent=`Status: ${d.status||'complete'} · ${d.elapsed_ms??0} ms · AUTO-CHAIN OFF`;document.getElementById('result-body').textContent=JSON.stringify(d.setup_result||d,null,2);document.getElementById('result-modal').classList.add('open');toast('Setup finished. Restart AgentWhite if the tool is not detected immediately.')}catch(e){toast(e.message,true);await load()}}async function runAction(id){toast('Running only the selected AgentWhite adapter…');try{const d=await api('/api/tool-action',{method:'POST',body:JSON.stringify({action_id:id})});state={tools:d.tools||state.tools,actions:d.actions||state.actions,runs:d.runs||state.runs,setup_summary:d.setup_summary||state.setup_summary};render();showResult(d);toast('Finished and saved. AgentWhite is waiting for your next button press.')}catch(e){toast(e.message,true);await load()}}function showResult(d){const r=d.result||{};document.getElementById('result-title').textContent=r.label||'TOOL RESULT';document.getElementById('result-meta').textContent=`Status: ${d.status||'complete'} · ${d.elapsed_ms??0} ms · AUTO-CHAIN OFF · Next action started: ${d.next_action_started?'YES':'NO'}`;document.getElementById('result-body').textContent=JSON.stringify(r.result||r,null,2);document.getElementById('result-modal').classList.add('open')}function closeResult(){document.getElementById('result-modal').classList.remove('open')}function renderHistory(){const rows=state.runs||[],el=document.getElementById('history');if(!rows.length){el.innerHTML='<div class="aw-empty">No tool actions have been run yet.</div>';return}el.innerHTML=rows.slice(0,30).map(r=>`<div class="aw-card history"><div class="aw-row"><div><div class="title">${esc(r.label)}</div><div class="aw-muted">${esc(r.tool_id)} · ${esc(r.action_id)} · ${esc(r.started_at)}</div></div><span class="aw-badge ${r.status==='success'?'ok':''} aw-right">${esc(r.status)}</span></div><div class="meta"><span class="aw-chip">${esc(r.effect)}</span><span class="aw-chip">${esc(r.scope)}</span><span class="aw-chip">${r.elapsed_ms} ms</span></div><button class="aw-btn" onclick='showSaved(${JSON.stringify(r.id)})'>View Saved Result</button></div>`).join('')}function showSaved(id){const r=(state.runs||[]).find(x=>x.id===id);if(!r)return;document.getElementById('result-title').textContent=r.label;document.getElementById('result-meta').textContent=`Saved result · ${r.status} · ${r.elapsed_ms} ms · ${r.started_at}`;document.getElementById('result-body').textContent=JSON.stringify(r.result||{},null,2);document.getElementById('result-modal').classList.add('open')}load().catch(e=>{document.getElementById('tools').innerHTML='<div class="aw-empty">'+esc(e.message)+'</div>';toast(e.message,true)});
</script></body></html>'''
TOOLS_HTML = TOOLS_HTML.replace("__AW_COMMON_CSS__", COMMON_CSS).replace("__AW_LOGO__", LOGO_DATA_URI)
